import { dateAndTimeToInstant, instantToHHMM, type LogUpdate, type LogWithLines } from '@motivation/shared';
import { HealthService } from '../../../services/health.service.js';
import { getAppTimeZone } from '../../../services/app-timezone.service.js';
import { navigate, returnTo } from '../../../router.js';
import { buildSectionPage } from '../../../utils/section-page.utils.js';
import { documentStyleSheet } from '../../../utils/css.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { safeExec } from '../../../utils/safe-exec.js';
import { bindPickedBarcode } from '../../../utils/bind-picked-barcode.js';
import { logLineView, toLineInput } from '../../../utils/line-view.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../../_shared/screen-status.js';
import { HEALTH_EVENTS, type LinePickedEvent, type LineSetDeleteEvent, type LineSetSaveEvent, type LineSetValue } from '../health-events.js';
import '../nutrition/line-set-editor/line-set-editor.component.js';
import '../nutrition/line-add-dialog/line-add-dialog.component.js';
import type { LineSetEditor } from '../nutrition/line-set-editor/line-set-editor.component.js';
import type { LineAddDialog } from '../nutrition/line-add-dialog/line-add-dialog.component.js';
import themeStyles from '../health-theme.css?inline';
import screenStyles from '../health-log-new-screen/health-log-new-screen.css?inline';

documentStyleSheet(themeStyles);
documentStyleSheet(screenStyles);

/** The day a log lives on. */
export function dayPath(date: string): string {
    return `/health/day/${encodeURIComponent(date)}`;
}

/**
 * Back to the day the editor was opened from (story 378: never stack the day twice), or — when the
 * log moved — to the day it moved to.
 */
export function returnToDay(from: string, to: string): void {
    if (from === to) returnTo(dayPath(from), dayPath(from));
    else navigate(dayPath(to), { history: 'replace' });
}

/**
 * Story 422 — a log in full (`/health/log/:id`): `<line-set-editor mode=log>` with its name, day,
 * slot and eaten-at time, ± on every line, add, remove and portion, Delete, and — for a log from a
 * meal — the opt-in "also update the meal" (418 #8). Save writes only what changed: `PATCH` for the
 * head, `PUT /lines` for the list, then the meal from the saved lines.
 */
export class HealthLogEditScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private idValue = '';
    private readonly body = document.createElement('div');
    private readonly log = createComponentLogger('health-log-edit-screen');
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    set logId(value: string) { this.idValue = value; }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;
        const page = buildSectionPage(this, 'Edit log', 'health', '/health');
        this.body.className = 'log-edit';
        this.statusNodes.retryNode.addEventListener('click', () => void this.load());
        page.content.append(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode, this.body);
        void this.load();
    }

    private async load(): Promise<void> {
        return safeExec(this, this.log, async () => {
            const log = await HealthService.findLog(this.idValue);
            if (!log) throw new Error(`Log ${this.idValue} not found.`);
            this.renderEditor(log);
        });
    }

    private renderEditor(log: LogWithLines): void {
        const editor = document.createElement('line-set-editor') as LineSetEditor;
        editor.setAttribute('mode', 'log');
        editor.setAttribute('deletable', '');
        if (log.meal_id) editor.setAttribute('meal-linked', '');
        customElements.upgrade(editor);
        editor.value = {
            name: log.name ?? '',
            date: log.date,
            meal_type: log.meal_type,
            time: log.consumed_at ? instantToHHMM(log.consumed_at, getAppTimeZone()) : '',
        };
        editor.lines = log.lines.map(logLineView);

        const add = document.createElement('line-add-dialog') as LineAddDialog;
        editor.addEventListener(HEALTH_EVENTS.LINE_ADD_REQUEST, () => add.open(log.meal_type));
        add.addEventListener(HEALTH_EVENTS.LINE_PICKED, (e: LinePickedEvent) => {
            editor.addLine(e.detail.line);
            void safeExec(this, this.log, () => bindPickedBarcode(e.detail.line, e.detail.bind));
        });
        editor.addEventListener(HEALTH_EVENTS.LINE_SET_SAVE, (e: LineSetSaveEvent) => { e.detail.respondWith = this.save(log, e.detail); });
        editor.addEventListener(HEALTH_EVENTS.LINE_SET_DELETE, (e: LineSetDeleteEvent) => {
            e.detail.respondWith = safeExec(this, this.log, async () => {
                await HealthService.deleteLog(log.id);
                returnToDay(log.date, log.date);
            });
        });
        this.body.replaceChildren(editor, add);
    }

    private async save(log: LogWithLines, value: LineSetValue): Promise<void> {
        return safeExec(this, this.log, async () => {
            const head = headChanges(log, value);
            if (Object.keys(head).length > 0) await HealthService.updateLog(log.id, head);

            const lines = value.lines.map(toLineInput);
            const before = log.lines.map((l) => toLineInput(logLineView(l)));
            let saved = log;
            if (JSON.stringify(lines) !== JSON.stringify(before)) saved = await HealthService.replaceLogLines(log.id, lines);

            if (value.also_update_meal && log.meal_id) await this.updateMeal(log.meal_id, saved);
            returnToDay(log.date, value.date);
        });
    }

    /** 418 #8: the meal takes the log's lines as they now are — every line has its food by then. */
    private async updateMeal(mealId: string, saved: LogWithLines): Promise<void> {
        const meal = await HealthService.getMeal(mealId);
        const orphaned = saved.lines.filter((l) => l.food_item_id === null).map((l) => l.food_name);
        if (orphaned.length > 0) throw new Error(`The log is saved, but the meal is not: ${orphaned.join(', ')} no longer in the food library.`);
        await HealthService.replaceMeal(mealId, {
            name: meal.name,
            notes: meal.notes,
            image_path: meal.image_path,
            ingredients: saved.lines.flatMap((l) => (l.food_item_id === null ? [] : [{ food_item_id: l.food_item_id, amount: l.amount }])),
        });
    }
}

/** What the head fields change: the name (empty is "named by its line"), day, slot and stamp. */
export function headChanges(log: LogWithLines, value: Pick<LineSetValue, 'name' | 'date' | 'meal_type' | 'time'>): LogUpdate {
    const update: LogUpdate = {};
    const name = value.name.trim() || null;
    if (name !== log.name) update.name = name;
    if (value.date !== log.date) update.date = value.date;
    if (value.meal_type !== log.meal_type) update.meal_type = value.meal_type;
    // Story 260: the HH:MM anchors on the (new) day in the app zone; cleared means unstamped.
    const tz = getAppTimeZone();
    const consumedAt = value.time ? dateAndTimeToInstant(value.date, value.time, tz) : null;
    const oldTime = log.consumed_at ? instantToHHMM(log.consumed_at, tz) : '';
    if (value.time !== oldTime || (consumedAt !== null && value.date !== log.date)) update.consumed_at = consumedAt;
    return update;
}

if (!customElements.get('health-log-edit-screen')) {
    customElements.define('health-log-edit-screen', HealthLogEditScreen);
}
